	@Test
	void differentMissingIrisShareOneMissingNamespaceProbe(@TempDir File directory) throws Exception {
		try (CountingValueStore store = store(directory)) {
			store.resetCounts();
			int initialSeeks = 0;

			for (int i = 0; i < 100; i++) {
				assertEquals(LmdbValue.UNKNOWN_ID, store.getId(VALUES.createIRI("urn:absent:term" + i)));
				if (i == 0) {
					initialSeeks = store.alternativeSeeks;
					assertTrue(initialSeeks > 0, "the cold lookup must inspect direct namespace prefixes");
				}
			}

			assertEquals(1, store.namespaceProbes, "the primary namespace absence is shared");
			assertEquals(0, store.valueProbes, "this empty fixture has no existing namespace for any URI candidate");
			assertTrue(store.alternativeProbes >= 100, "distinct IRIs still check hash-indexed namespace prefixes");
			assertEquals(initialSeeks, store.alternativeSeeks,
					"the shared ancestor proof must also eliminate repeated direct namespace seeks");
		}
	}

