	@Test
	void distinctChildNamespacesReuseEverySharedAncestorProofAtDefaultCapacity(@TempDir File directory)
			throws Exception {
		String parent = "urn:shared:" + "longnamespace".repeat(8) + "/";
		try (CountingValueStore store = store(directory)) {
			Set<Long> sharedHashes = new HashSet<>();
			for (int length = ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES; length <= parent.length(); length++) {
				sharedHashes.add(ValueStoreRecordCodec.hash(
						ValueStoreRecordCodec.namespaceData(parent.substring(0, length))));
			}
			store.watchedNamespaceHashes = sharedHashes;
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(VALUES.createIRI(parent + "record0/category")));
			assertTrue(store.watchedNamespaceProbes > 0, "the cold lookup must physically examine the shared range");
			for (int i = 1; i <= 100; i++) {
				store.resetCounts();
				assertEquals(LmdbValue.UNKNOWN_ID, store.getId(VALUES.createIRI(parent + "record" + i + "/category")));
				assertTrue(store.alternativeProbes > 0, "each changed child still requires physical namespace checks");
				assertEquals(0, store.watchedNamespaceProbes,
						"a distinct child must reuse every shared ancestor-prefix proof, child " + i);
			}
		}
	}

